                    if not opts['yes']:
                        log("Do you want to decompress '" + chr(34) + display_path(path) + chr(34) + "'?")
                        log("Stdin is null, can't read user input (bypass with --yes, but be careful)")
                        continue
                lines=list_archive(path,opts['tree'],'.'.join(list_formats) if list_formats else None)
                if lines:
                    lines[0]=f'Archive: "{display_path(path)}"'
                if opts['quiet']: lines=lines[1:]
                for line in lines: print(line)
                if zip_stream_warning and opts['yes']:
                    log(ZIP_STREAM_WARNING)
                if detected and not opts['quiet']:
                    log(f'[WARNING] No recognized extensions in "{display_path(path)}". Proceeding with `{detected[-1]}` that was detected from the file signature.')
